// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for cf-conf-load: defaults, parse, bad values
// Flo: arena > parse json strings > assert values or BadConfig
// I/O: json text > Conf or error
// Run: zig build test
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig");
fn arenNewz() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
test "defaults are free-only" { const conf: cfgz.Conf = .{}; try std.testing.expectEqual(@as(u64, 0), cfgz.capzMicr(conf)); try std.testing.expectEqualStrings("purg", conf.clou_poli_mode); try std.testing.expect(!conf.logi_mode_enab); try cfgz.confChek(conf); }
test "parse keeps given keys" { var aren = arenNewz(); defer aren.deinit(); const conf = try cfgz.confPars(aren.allocator(), "{\"capz_usdz_mont\": 1.5, \"vend_orde\": [\"zenr\"]}"); try std.testing.expectEqual(@as(u64, 1500000), cfgz.capzMicr(conf)); try std.testing.expectEqual(@as(usize, 1), conf.vend_orde.len); try std.testing.expectEqual(@as(u32, 30), conf.fetc_time_seco); }
test "clou_endp keys reach the Endp fields (host, regn, bukt, dbnm)" { var aren = arenNewz(); defer aren.deinit(); const conf = try cfgz.confPars(aren.allocator(), "{\"clou_endp\":{\"turs\":{\"host\":\"h.example\"},\"b2zz\":{\"bukt\":\"bk\",\"regn\":\"r1\"},\"tidb\":{\"dbnm\":\"d1\"}}}"); try std.testing.expectEqualStrings("h.example", conf.clou_endp.turs.host); try std.testing.expectEqualStrings("bk", conf.clou_endp.b2zz.bukt); try std.testing.expectEqualStrings("r1", conf.clou_endp.b2zz.regn); try std.testing.expectEqualStrings("d1", conf.clou_endp.tidb.dbnm); }
test "bad values are refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const bads = [_][]const u8{ "{\"capz_usdz_mont\": -1}", "{\"clou_poli_mode\": \"drop\"}", "{\"vend_orde\": []}", "{\"vend_orde\": [\"nope\"]}", "{\"fetc_time_seco\": 0}", "{\"capz_disk_gbyt\": 0}", "not json", "{\"logi_mode_enab\": 7}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confPars(allo, badz)); }
test "missing file gives defaults" { var aren = arenNewz(); defer aren.deinit(); const conf = try cfgz.confLoad(aren.allocator(), std.testing.io, "no-such-dir/aa-conf-main.json"); try std.testing.expectEqual(@as(u32, 5), conf.capz_disk_gbyt); }
test "car row keys: defaults are the locked retention, bad values are refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const conf: cfgz.Conf = .{}; try std.testing.expect(conf.carz_enab); try std.testing.expectEqual(@as(u32, 180), conf.carz_text_days); try std.testing.expectEqual(@as(u32, 365), conf.carz_hist_days); try std.testing.expectEqual(@as(u32, 730), conf.carz_gone_days); try std.testing.expectEqual(@as(u32, 90), conf.carz_pers_days); try std.testing.expectEqual(@as(u32, 14), conf.carz_stal_days); try std.testing.expectEqual(@as(u32, 90), conf.carz_dead_days); const good = try cfgz.confPars(allo, "{\"carz_text_days\": 30, \"carz_hist_days\": 60}"); try std.testing.expectEqual(@as(u32, 30), good.carz_text_days); const bads = [_][]const u8{ "{\"carz_text_days\": 0}", "{\"carz_pull_maxz\": 0}", "{\"carz_stal_days\": 90}", "{\"carz_text_days\": 800}", "{\"carz_hist_days\": 800}", "{\"cont_week_keep\": 0}", "{\"cont_week_keep\": 53}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confPars(allo, badz)); }
test "purge keys: defaults are the verified plan, bad values are refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const conf: cfgz.Conf = .{}; try std.testing.expectEqual(@as(u32, 30), conf.purg_loca_days); try std.testing.expectEqual(@as(u32, 80), conf.purg_high_pctz); try std.testing.expectEqual(@as(u32, 60), conf.purg_lowz_pctz); try std.testing.expectEqual(@as(u32, 90), conf.purg_clou_mini_days); try std.testing.expectEqual(@as(f64, 8), conf.clou_capz_gbyt.b2zz); try std.testing.expectEqual(@as(u32, 8192), conf.clou_body_maxz); try std.testing.expect(conf.purg_copy_enab); const good = try cfgz.confPars(allo, "{\"purg_high_pctz\": 70, \"purg_lowz_pctz\": 50, \"purg_tras_days\": 0}"); try std.testing.expectEqual(@as(u32, 70), good.purg_high_pctz); const bads = [_][]const u8{ "{\"purg_high_pctz\": 101}", "{\"purg_lowz_pctz\": 80}", "{\"purg_lowz_pctz\": 0}", "{\"purg_maxx_pctz\": 0}", "{\"purg_dead_pctz\": 101}", "{\"purg_loca_days\": 0}", "{\"purg_veri_cont\": 101}", "{\"clou_fail_runs\": 0}", "{\"clou_body_maxz\": 100}", "{\"clou_body_maxz\": 70000}", "{\"clou_sqlz_capz_mbyt\": {\"turs\": 0}}", "{\"clou_capz_gbyt\": {\"b2zz\": 0}}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confPars(allo, badz)); }
test "social keys: defaults, engine entry needs a pipe, limits are refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const conf: cfgz.Conf = .{}; try std.testing.expect(conf.soci_enab); try std.testing.expectEqual(@as(u32, 20000), conf.soci_line_maxz); try std.testing.expectEqual(@as(usize, 0), conf.soci_engi_list.len); const goodz = try cfgz.confPars(allo, "{\"soci_engi_list\": [\"fb|C:/x/fb.exe|read\"]}"); try std.testing.expectEqual(@as(usize, 1), goodz.soci_engi_list.len); const bads = [_][]const u8{ "{\"soci_engi_list\": [\"fb\"]}", "{\"soci_line_maxz\": 10}", "{\"soci_time_seco\": 0}", "{\"soci_file_maxz\": 300, \"soci_line_maxz\": 1000}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confPars(allo, badz)); }
test "an unknown key is refused (top level, nested, and a typo of a real key)" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const bads = [_][]const u8{ "{\"unkn_keyz\": 1}", "{\"capz_usdz_mon\": 1}", "{\"clou_endp\":{\"turs\":{\"hostt\":\"h\"}}}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confPars(allo, badz)); try std.testing.expectEqualStrings("unkn_keyz", cfgz.confKeyz(allo, "{\"capz_usdz_mont\": 1, \"unkn_keyz\": 1}").?); try std.testing.expect(cfgz.confKeyz(allo, "{\"capz_usdz_mont\": 1}") == null); }
test "run deadline: default stays under the hub step timeout, zero and huge are refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const conf: cfgz.Conf = .{}; try std.testing.expectEqual(@as(u32, 3300), conf.runz_time_seco); const bads = [_][]const u8{ "{\"runz_time_seco\": 0}", "{\"runz_time_seco\": 59}", "{\"runz_time_seco\": 86401}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confPars(allo, badz)); const goodz = try cfgz.confPars(allo, "{\"runz_time_seco\": 600}"); try std.testing.expectEqual(@as(u32, 600), goodz.runz_time_seco); }
test "the shipped aa-conf-main.json passes the strict loader" { var aren = arenNewz(); defer aren.deinit(); _ = try std.Io.Dir.cwd().statFile(std.testing.io, "aa-conf-main.json", .{}); _ = try cfgz.confLoad(aren.allocator(), std.testing.io, "aa-conf-main.json"); }
test "politeness floor: a zero per-host gap is refused (no setting can make the fetcher instant)" { var aren = arenNewz(); defer aren.deinit(); try std.testing.expectError(error.BadConfig, cfgz.confPars(aren.allocator(), "{\"rate_host_seco\": 0}")); const okz = try cfgz.confPars(aren.allocator(), "{\"rate_host_seco\": 1}"); try std.testing.expectEqual(@as(u32, 1), okz.rate_host_seco); }
